#!/usr/bin/env python3
# Writes src/diag_table.h from spec/registry/diagnostics.md: the registry
# the runtime's fault reports are rendered from. cobc embeds the file and
# parses it when it runs (impl/cobc/diags.cb `parse_registry`); the
# runtime gets the parsed table, generated by this script and checked in,
# so the parse below mirrors `parse_registry` exactly: a line, trimmed,
# that starts with "- `diag.", split at the first " — ", the ids in
# backticks before it, each known label's first occurrence after it, a
# field running to the next label found, trimmed, its trailing '.'s and
# then ' 's removed. A later line naming the same id replaces an earlier
# one (a HashMap insert).
#
# Usage: python3 -I tools/gen_diag_table.py REGISTRY.md OUT.h
import sys

LABELS = ["Summary: ", "Phase: ", "Rule: ", "Invariant: ", "Required: ",
          "Observed: ", "Provenance: ", "Repair: ", "Related: ", "Location: "]
KEYS = ["summary", "phase", "rule", "invariant", "required", "observed",
        "provenance", "repair", "related", "location"]

# Ids the registry gives the static phase that the generated C raises at
# run time where the static pass left the decision to it (impl/back writes
# them into `cb_fault` calls; the runtime's own sources name the first two).
AT_RUN_TIME_TOO = {"diag.move-out-of-field", "diag.read-of-resource", "diag.type-mismatch"}

# Rust's `char::is_whitespace` (Unicode White_Space).
WS = "\t\n\x0b\x0c\r \x85\xa0       " \
     "         　"


def rtrim(s):
    return s.strip(WS)


def ids_of(names):
    ids, rest = [], names
    while True:
        a = rest.find("`")
        if a < 0:
            break
        after = rest[a + 1:]
        b = after.find("`")
        if b < 0:
            break
        cand = after[:b]
        if cand.startswith("diag."):
            ids.append(cand)
        rest = after[b + 1:]
    return ids


def fields_of(part):
    pos = sorted((part.find(l), l) for l in LABELS if part.find(l) >= 0)
    out = {}
    for i, (p, label) in enumerate(pos):
        start = p + len(label)
        end = pos[i + 1][0] if i + 1 < len(pos) else len(part)
        v = rtrim(part[start:end]).rstrip(".").rstrip(" ")
        out[label[:-2].lower()] = v
    return out


def c_str(s):
    if s is None:
        return "NULL"
    b = s.encode("utf-8")
    out = []
    for c in b:
        if c in (0x22, 0x5c):
            out.append("\\" + chr(c))
        elif 0x20 <= c < 0x7f and c != 0x3f:
            out.append(chr(c))
        else:
            out.append("\\%03o" % c)
    return '"' + "".join(out) + '"'


def main():
    src, dst = sys.argv[1], sys.argv[2]
    text = open(src, encoding="utf-8").read()
    table = {}
    # Rust's `str::lines`: split at '\n', a trailing '\r' removed.
    for line in text.split("\n"):
        if line.endswith("\r"):
            line = line[:-1]
        line = rtrim(line)
        if not line.startswith("- `diag."):
            continue
        rest = line[2:]
        k = rest.find(" — ")
        if k < 0:
            continue
        names, part = rest[:k], rest[k + 3:]
        ids = ids_of(names)
        if not ids:
            continue
        f = fields_of(part)
        for i in ids:
            table[i] = f
    # The fields the runtime renders (`Phase` and `Location` it never reads),
    # each an offset into one text; 0: the entry has no such field. No
    # pointer: a table of pointers costs a relocation each in every program.
    fields = ["id", "summary", "rule", "invariant", "required", "observed",
              "provenance", "repair", "related"]
    blob = bytearray(b"\0")
    rows = []
    for i in sorted(table, key=lambda s: s.encode("utf-8")):
        # Only what a running program can raise: an entry whose Phase names
        # the dynamic phase, and the ids the generated C raises though the
        # registry calls them static. The compiler's own diagnostics are
        # rendered by the compiler, from the whole registry.
        ph = table[i].get("phase", "")
        if not ("dynamic" in ph or "both" in ph or i in AT_RUN_TIME_TOO):
            continue
        f = dict(table[i])
        f["id"] = i
        row = []
        for k in fields:
            v = f.get(k)
            if v is None:
                row.append(0)
            else:
                row.append(len(blob))
                blob += v.encode("utf-8") + b"\0"
        rows.append((row, i))
    if len(blob) > 0xffff:
        sys.exit("gen_diag_table.py: the registry's text is %d bytes, past a 16-bit offset" % len(blob))
    lines = ["/* Generated by tools/gen_diag_table.py from spec/registry/diagnostics.md:",
             "   do not edit. The registry's entries a running program can raise,",
             "   sorted by id (diagnostics.c looks an id up by binary search): each",
             "   field is an offset into DIAG_TEXT, 0 where the entry has none. */", "",
             "enum", "{"]
    lines += ["    DG_%s," % k.upper() for k in fields]
    lines += ["    DG_FIELDS", "};", "", "static const char DIAG_TEXT[%d] =" % len(blob)]
    text = bytes(blob[:-1])
    for part in text.split(b"\0"):
        lines.append("    " + c_str(part.decode("utf-8")) + ' "\\0"')
    lines[-1] = lines[-1][:-len(' "\\0"')] + ";"
    lines += ["", "static const uint16_t DIAG_TABLE[][DG_FIELDS] =", "{"]
    for row, i in rows:
        lines.append("    {%s}, /* %s */" % (", ".join(str(x) for x in row), i))
    lines += ["};", "",
              "#define DIAG_TABLE_LEN (sizeof DIAG_TABLE / sizeof DIAG_TABLE[0])", ""]
    open(dst, "w", encoding="utf-8").write("\n".join(lines))

main()
